DEFAULT_TEMPERATURE_MAP: Dict[str, float] = {'gemma-4-31b': 0.7, 'qwen2.5-coder-7b': 0.7, 'deepseek-coder-7b': 0.5}
TOP_P_MAP: Dict[str, float] = {'gemma-4-31b': 0.95, 'qwen2.5-coder-7b': 0.8, 'deepseek-coder-7b': 0.95}
TOP_K_MAP: Dict[str, int] = {'gemma-4-31b': 64, 'qwen2.5-coder-7b': 40, 'deepseek-coder-7b': 40}
