def get_sampling_params(model_name: str, role: Optional[str]=None, temperature: Optional[float]=None) -> Dict[str, Any]:
    if model_name not in DEFAULT_TEMPERATURE_MAP:
        raise KeyError(f'Unknown model: {model_name}')
    t = temperature if temperature is not None else DEFAULT_TEMPERATURE_MAP[model_name]
    return {'temperature': t, 'top_p': TOP_P_MAP.get(model_name, 0.95), 'top_k': TOP_K_MAP.get(model_name, 40), 'thinking': False}

def cross_context_for(p_fb: float, other_critiques: List[str], rng: Optional[random.Random]=None) -> str:
    if rng is None:
        rng = random.Random()
    if other_critiques and rng.random() < p_fb:
        chosen = rng.choice(other_critiques)
        return 'A critique from a different reasoning path (use it only if it applies here):\n' + chosen + '\n'
    return ''
