PROMPT_NETWORK_UPDATE = '[MAC NETWORK UPDATE - EvoMAC-inspired]\nCurrent Network: {current_network}\nTextual Gradients: {textual_gradients}\nMissing Subtasks: {missing_subtasks}\n\n[INSTRUCTION]\nUpdate the MAC network based on textual gradients:\n1. Remove agents whose subtasks are completed\n2. Revise erroneous agent prompts by adding potential solutions from gradient analysis\n3. Add new agents for missing subtasks\n4. Restructure workflows based on subtask dependencies\n\n[STRICT OUTPUT MANDATE]\nOutput RAW JSON ONLY. Start with \'{\' and end with \'}\'.\n{\n  "agents_to_remove": ["string"],\n  "agents_to_revise": [\n    {\n      "agent_id": "string",\n      "prompt_addition": "string (≤ 50 words)"\n    }\n  ],\n  "agents_to_add": [\n    {\n      "agent_id": "string",\n      "role": "string",\n      "subtask": "string",\n      "dependencies": ["string"]\n    }\n  ],\n  "workflow_changes": "string (≤ 60 words)"\n}'
PROMPT_DYNAMIC_ROLE_ASSIGNMENT = "[DYNAMIC ROLE ASSIGNMENT REQUEST]\nTask Phase: {task_phase}\nRequired Expertise: {required_expertise}\nAvailable Agent Capabilities: {agent_capabilities}\n\n[INSTRUCTION]\nAssign the most suitable agent role for the current task phase.\nConsider the agent's historical performance and the task's abstraction level.\n\n[STRICT OUTPUT MANDATE]\nOutput the assigned role name ONLY (≤ 15 words). No explanation."
PROMPT_FEEDBACK_FROM_LOCALISATION = '[FLARE-GNN FEEDBACK LOCALISATION]\nFailing assertions:\n{failures}\n\nStatements ranked by the fault-localisation model after the tests (line, score, code):\n{statement_scores}\n\nCode with line numbers:\n{repair_context}\n\nRoot-cause analysis (may be empty):\n{root_cause}\n\n[INSTRUCTION]\nTurn this into at most {max_items} localised feedback items for the programmer.\nUse ONLY lines that appear above. Say what is wrong at that place and in which direction\nthe fix lies; do NOT write the fix itself.\n\n[STRICT OUTPUT MANDATE]\nOutput RAW JSON ONLY. Start with \'{\' and end with \'}\'.\n{{\n  "items": [\n    {{\n      "file": "string",\n      "lines": "string (e.g. 14-18)",\n      "problem": "string (≤ 30 words)",\n      "fix_direction": "string (≤ 25 words)"\n    }}\n  ]\n}}'
PROMPT_INITIAL_TDD_GENERATION = "[INITIAL TDD TEST GENERATION - PRE-CODE]\nSubtask ID: {subtask_id}\nSubtask Goal: {subtask_goal}\n\n[REASONING PLAN FROM GOTGNN]\n{reasoning_plan}\n\n[SCPG INTERFACE CONTRACTS]\n{interface_contracts}\n\n[INSTRUCTION]\nWrite the initial test suite BEFORE any code exists.\nDerive every expected value from the requirement and the contracts only.\nNever use the current code's output (it does not exist yet).\nCover: normal path, boundary conditions, and invariants.\n\n[STRICT ZERO-COMMENTS & PYTHON OUTPUT MANDATE]\n1. TARGET LANGUAGE: PYTHON ONLY (PyTest / Unittest).\n2. STRICT ZERO-COMMENTS: Absolutely NO comments (inline or block), docstrings, or placeholder text."
PROMPT_DYNAMIC_CODING_INITIAL = '[CODING TEAM TASK ASSIGNMENT - ITERATION 1]\nRequirement: {requirement}\nSubtask ID: {subtask_id}\nTarget Files: {target_files}\n\n[GOTGNN REASONING PATH GUIDANCE]\nOptimal Thought Path (pi*): {best_path_nodes}\nPredicted Action: {action_type}\nRecommended Steps: {action_count}\n\n[SCPG SCAFFOLDING INTERFACE CONTRACTS]\n{scaffolding_contracts}\n\n[ACTIVE PEM ADVISOR RULES]\n{retrieved_advice}\n\n[INSTRUCTION]\nSynthesize the complete, production-grade implementation for the target files.\nAdhere strictly to the contracts and defensive rules above.\n\n[STRICT ZERO-COMMENTS & PYTHON OUTPUT MANDATE]\n1. TARGET LANGUAGE: PYTHON ONLY (Python 3.10+).\n2. STRICT ZERO-COMMENTS: Absolutely NO comments (inline or block), docstrings, or placeholder text.'
PROMPT_DYNAMIC_CODING_ITERATIVE_REPAIR = '[CODING TEAM SURGICAL REPAIR - ITERATION {iteration}]\nRequirement: {requirement}\nSubtask ID: {subtask_id}\n\nLocalised feedback:\n{feedback}\n\nEditable regions (line numbers refer to the current files):\n{repair_context}\n\n{plan_block}\n\nRules from earlier failures:\n{advice}\n\nBehaviour that must keep working (tests that currently pass):\n{passing_summary}\n\n[INSTRUCTION]\nFix the defects with the smallest edit. Change only lines inside the editable regions.\nIf the defect cannot be fixed inside the editable regions, reply only:\n=== NO_EDIT: <one-line reason> ===\n\n[STRICT ZERO-COMMENTS & PYTHON REPLACEMENT MANDATE]\n1. TARGET LANGUAGE: PYTHON ONLY.\n2. STRICT ZERO-COMMENTS: Absolutely NO comments (inline or block), docstrings, or placeholder text.'
PROMPT_DYNAMIC_TEST_GENERATION = '[TEST TEAM - DYNAMIC TEST SUITE GENERATION]\nComponent: {component_name}\nTarget Language: PYTHON ONLY (PyTest / Unittest)\nInterface Contracts:\n{interface_contracts}\n\nStatements that the fault-localisation model ranks as most suspicious before any test has run,\nhighest first (line, score, code):\n{suspicious_statements}\n\nCode around them:\n{repair_context}\n\n[INSTRUCTION]\nGenerate an exhaustive test suite targeting execution criteria:\n1. Write tests that reach the suspicious statements first, then cover normal use and boundary inputs.\n2. Derive every expected value from the requirement and the contracts, never from what the current code returns.\n3. Tests must be deterministic and must not modify the source.\n\n[STRICT ZERO-COMMENTS & PYTHON OUTPUT MANDATE]\n1. TARGET LANGUAGE: PYTHON ONLY (PyTest / Unittest compatible).\n2. STRICT ZERO-COMMENTS: Absolutely NO comments (inline or block), docstrings, or placeholder text.'
PROMPT_TEXTUAL_BACKPROP_ANALYZER = '[TEXTUAL BACKPROPAGATION - ROOT CAUSE DEDUCTION]\nIteration: {iteration}\nSubtask: {subtask_id}\nSubtasks it depends on: {dependencies}\n\n[EXECUTION FEEDBACK SIGNAL]\nPass Rate: {passed_count}/{total_count} ({pass_percentage:.1f}%)\nFailing Test Assertions:\n{failures_list}\n\n[FLARE-GNN FAULT LOCALIZATION]\nStatement Fault Probabilities: {stmt_fault_scores}\nRoot Cause Seed Statements: {seed_stmts}\nMAD Threshold: {mad_threshold}\n\nCode of the suspicious region:\n{repair_context}\n\n[INSTRUCTION]\nDecide where the failure originates:\n- "current_subtask": the logic of {subtask_id} is wrong.\n- "upstream_subtask": the failure comes from the output of a subtask it depends on; give its id.\n- "unclear": the evidence does not decide.\n\nBase every claim on the failures and the code above.\n\n[STRICT OUTPUT MANDATE]\nOutput RAW JSON ONLY. Start directly with \'{\' and end directly with \'}\'.\n{{\n  "origin": "current_subtask|upstream_subtask|unclear",\n  "upstream_subtask_id": "string (if origin is upstream_subtask, else null)",\n  "root_cause": "string (≤ 40 words)",\n  "failure_pattern": "string",\n  "evidence": ["string (≤ 20 words each)"],\n  "suspected_thought_nodes": ["string (node ids)"],\n  "graph_critique": "string (≤ 25 words)",\n  "pem_advice_rule": "string (≤ 20 words)",\n  "affected_roles": ["Architect | StateCoordinator | Generator | QA"]\n}}'
PROMPT_TEXTUAL_BACKPROP_PROMPT_UPDATER = '[TEXTUAL BACKPROPAGATION - DYNAMIC PROMPT UPDATE]\nTarget Agent Role: {agent_role}\nCurrent Iteration: {iteration}\nDeducted Failure Pattern: {failure_pattern}\n\n[BACKPROPAGATED CRITIQUE & LESSON]\n{critique_statement}\nActive Advice: {advice_rule}\n\n[INSTRUCTION]\nDynamically update the system constraints for {agent_role} for Round {iteration_plus_one}.\nAdd a strict negative constraint forbidding the pattern that caused the failure, and inject a required verification step.\n\n[STRICT OUTPUT MANDATE]\nOutput updated directive statement ONLY (≤ 40 words). No conversational fluff.'
PROMPT_THOUGHT_GRAPH_REFINEMENT = '[THOUGHT GRAPH REFINEMENT]\nCurrent Graph Nodes: {current_nodes}\nFailed Reasoning Path: {failed_path}\nRoot Cause: {root_cause}\nRepair Context (Flare-GNN subgraph): {repair_context}\nPEM Advice: {advice}\n\n[INSTRUCTION]\nAdd new critique and refinement nodes to the graph to prevent this failure in the next iteration.\n1. Add ONE critique node addressing the root cause.\n2. Add ONE refinement node that resolves the critique.\n3. Specify edges to connect them to existing nodes (use existing node ids).\n\n[STRICT OUTPUT MANDATE]\nOutput RAW JSON ONLY. Start with \'{\' and end with \'}\'.\n{\n  "new_nodes": [\n    {\n      "node_type": "critique",\n      "content": "string (≤ 50 words)",\n      "connects_to": ["existing_node_id"],\n      "edge_type": "critiques"\n    },\n    {\n      "node_type": "refine",\n      "content": "string (≤ 60 words)",\n      "connects_to": ["critique_node_temp_id"],\n      "edge_type": "informs"\n    }\n  ],\n  "aggregation_edges": [\n    {\n      "source": "existing_node_id",\n      "target": "existing_node_id",\n      "edge_type": "aggregates"\n    }\n  ]\n}\n'

class DynamicCodingTeamPromptBuilder:

    @staticmethod
    def build_initial(requirement: str, subtask_id: str, target_files: List[str], plan_got: Dict[str, Any], scpg_contracts: str, pem_advice: List[str], model_name: str='gemma-4-31b') -> Dict[str, Any]:
        advice_str = '\n'.join([f'- {a}' for a in pem_advice]) if pem_advice else 'None active.'
        prompt = PROMPT_DYNAMIC_CODING_INITIAL.format(requirement=requirement, subtask_id=subtask_id, target_files=', '.join(target_files), best_path_nodes=str(plan_got.get('best_path', [])), action_type=plan_got.get('action_type', 'EXPAND'), action_count=plan_got.get('action_count', 3), scaffolding_contracts=scpg_contracts, retrieved_advice=advice_str)
        return {'prompt': prompt, 'sampling': get_sampling_params(model_name=model_name, role='generator')}

    @staticmethod
    def build_repair(requirement: str, subtask_id: str, iteration: int, flare_post: Dict[str, Any], test_results: Dict[str, Any], localized_subgraph: str, pem_advice: str, feedback: str='(see failing assertions below)', plan_block: str='', passing_summary: str='(none recorded)', model_name: str='gemma-4-31b') -> Dict[str, Any]:
        prompt = PROMPT_DYNAMIC_CODING_ITERATIVE_REPAIR.format(iteration=iteration, requirement=requirement, subtask_id=subtask_id, feedback=feedback, repair_context=localized_subgraph, plan_block=plan_block, advice=pem_advice, passing_summary=passing_summary)
        return {'prompt': prompt, 'sampling': get_sampling_params(model_name=model_name, role='repair')}

class DynamicFeedbackLocalisationBuilder:

    @staticmethod
    def build(failures: List[str], stmt_scores: Dict[str, Any], repair_context: str, root_cause: str='', max_items: int=5) -> str:
        failures_str = '\n'.join([f'- {f}' for f in failures])
        scores_str = '\n'.join([f'line {ln}: score={sc:.4f} | {cd}' for ln, sc, cd in sorted(stmt_scores.items(), key=lambda x: -x[1]) if isinstance(sc, float)]) if isinstance(stmt_scores, dict) else str(stmt_scores)
        return PROMPT_FEEDBACK_FROM_LOCALISATION.format(failures=failures_str, statement_scores=scores_str, repair_context=repair_context, root_cause=root_cause or '(not yet computed)', max_items=max_items)

class DynamicTestTeamPromptBuilder:

    @staticmethod
    def build_generator_prompt(component_name: str, interface_contracts: str, suspicious_statements: str='(none)', repair_context: str='(none)', model_name: str='gemma-4-31b') -> Dict[str, Any]:
        prompt = PROMPT_DYNAMIC_TEST_GENERATION.format(component_name=component_name, interface_contracts=interface_contracts, suspicious_statements=suspicious_statements, repair_context=repair_context)
        return {'prompt': prompt, 'sampling': get_sampling_params(model_name=model_name, role='qa')}

    @staticmethod
    def build_initial_tdd(subtask_id: str, subtask_goal: str, reasoning_plan: str, interface_contracts: str, model_name: str='gemma-4-31b') -> Dict[str, Any]:
        prompt = PROMPT_INITIAL_TDD_GENERATION.format(subtask_id=subtask_id, subtask_goal=subtask_goal, reasoning_plan=reasoning_plan, interface_contracts=interface_contracts)
        return {'prompt': prompt, 'sampling': get_sampling_params(model_name=model_name, role='qa')}

class DynamicTextualBackpropBuilder:

    @staticmethod
    def build_analyzer_prompt(iteration: int, subtask_id: str, path_nodes: List[int], test_results: Dict[str, Any], flare_post: Dict[str, Any]) -> str:
        total = test_results.get('total_count', 1)
        passed = test_results.get('passed_count', 0)
        pct = passed / total * 100.0 if total > 0 else 0.0
        failures = '\n'.join([f'- {f}' for f in test_results.get('failures', [])])
        return PROMPT_TEXTUAL_BACKPROP_ANALYZER.format(iteration=iteration, subtask_id=subtask_id, path_nodes=str(path_nodes), passed_count=passed, total_count=total, pass_percentage=pct, failures_list=failures, stmt_fault_scores=str(flare_post.get('stmt_scores', {})), seed_stmts=str(flare_post.get('seed_stmts', [])), mad_threshold=f"{flare_post.get('mad_threshold', 0.5):.4f}")

    @staticmethod
    def build_prompt_update(agent_role: str, iteration: int, failure_pattern: str, critique: str, advice: str) -> str:
        return PROMPT_TEXTUAL_BACKPROP_PROMPT_UPDATER.format(agent_role=agent_role, iteration=iteration, iteration_plus_one=iteration + 1, failure_pattern=failure_pattern, critique_statement=critique, advice_rule=advice)
MASTER_PROMPT_REGISTRY: Dict[str, Dict[str, Any]] = {'output_formatting': {'guardrail': STRICT_FORMATTING_GUARDRAIL}, 'abstraction_levels': {'level_1_architecture': SYSTEM_PROMPT_ARCHITECT, 'level_2_module': SYSTEM_PROMPT_MODULE_COORDINATOR, 'level_3_class_state': SYSTEM_PROMPT_STATE_COORDINATOR, 'level_4_function': SYSTEM_PROMPT_FUNCTION_ENGINEER, 'level_5_statement': SYSTEM_PROMPT_STATEMENT_GENERATOR}, 'dynamic_teams': {'architect': SYSTEM_PROMPT_ARCHITECT, 'module_coordinator': SYSTEM_PROMPT_MODULE_COORDINATOR, 'dynamic_planner': SYSTEM_PROMPT_DYNAMIC_PLANNER, 'code_generator': SYSTEM_PROMPT_CODE_GENERATOR, 'state_coordinator': SYSTEM_PROMPT_STATE_COORDINATOR, 'qa_engineer': SYSTEM_PROMPT_QA_ENGINEER}, 'thought_graph_config': {'task_decomposition': PROMPT_TASK_DECOMPOSITION, 'config_selection': PROMPT_THOUGHT_GRAPH_CONFIG, 'node_scoring': PROMPT_NODE_SCORING}, 'thought_reasoning': {'root_decomposition': PROMPT_ROOT_DECOMPOSITION, 'five_d_critique': PROMPT_5D_CRITIQUE, 'refinement': PROMPT_REFINEMENT, 'similarity_aggregation': PROMPT_SIMILARITY_AGGREGATION, 'task_dependency_aggregation': PROMPT_TASK_DEPENDENCY_AGGREGATION, 'thought_validation': PROMPT_THOUGHT_VALIDATION, 'validate_and_improve': PROMPT_VALIDATE_AND_IMPROVE, 'thought_graph_refinement': PROMPT_THOUGHT_GRAPH_REFINEMENT}, 'meta_controller': {'gnn_steering_injection': PROMPT_GNN_STEERING_INJECTION}, 'memory_advisor': {'advice_retrieval_injection': PROMPT_PEM_ADVICE_RETRIEVAL_INJECTION, 'rule_formulation': PROMPT_PEM_RULE_FORMULATION, 'context_compression': PROMPT_CONTEXT_EVICTION_COMPRESSION}, 'repair_healing': {'flare_gnn_diagnostic': PROMPT_FLARE_GNN_DIAGNOSTIC, 'surgical_patch': PROMPT_PEM_SURGICAL_PATCH, 'cascade_error_breaker': PROMPT_CASCADE_ERROR_BREAKER}, 'role_evolution': {'role_evolution_analyzer': PROMPT_ROLE_EVOLUTION_ANALYZER, 'dynamic_role_assignment': PROMPT_DYNAMIC_ROLE_ASSIGNMENT, 'gradient_analysis': PROMPT_GRADIENT_ANALYSIS, 'network_update': PROMPT_NETWORK_UPDATE}, 'dynamic_multi_team': {'coding_initial': PROMPT_DYNAMIC_CODING_INITIAL, 'coding_repair': PROMPT_DYNAMIC_CODING_ITERATIVE_REPAIR, 'test_generation': PROMPT_DYNAMIC_TEST_GENERATION, 'initial_tdd_generation': PROMPT_INITIAL_TDD_GENERATION, 'feedback_from_localisation': PROMPT_FEEDBACK_FROM_LOCALISATION, 'textual_backprop_analyzer': PROMPT_TEXTUAL_BACKPROP_ANALYZER, 'textual_backprop_prompt_updater': PROMPT_TEXTUAL_BACKPROP_PROMPT_UPDATER}}

def get_prompt(category: str, prompt_key: str, **kwargs) -> str:
    raw_prompt = MASTER_PROMPT_REGISTRY.get(category, {}).get(prompt_key)
    if not raw_prompt:
        raise KeyError(f"Prompt '{prompt_key}' in category '{category}' not found in registry.")
    if kwargs:
        return raw_prompt.format(**kwargs)
    return raw_prompt
